#!/usr/bin/env node
/**
 * judge-calibration-record.mjs — regenerate the judge recordings (FRW-BL-087)
 *
 * WHY
 *   The recordings in framework/quality/calibration/judge-outputs/ were previously regenerated by
 *   a MANUAL by-hand procedure documented in the calibration README. That meant the harness built
 *   to detect grade inflation could silently validate a stale judge whenever card-reviewer.md
 *   changed — nobody re-recorded, because re-recording was tedious and undocumented in code.
 *
 * ⚠️  RUN THIS FROM A PLAIN SHELL — NEVER FROM INSIDE A VOLUNDR SESSION.
 *   It shells out to `claude -p`, which HANGS INDEFINITELY in nested sessions
 *   (framework/system-instructions.md § "NEVER use `claude -p`"). This script refuses to run when
 *   it detects a Claude Code session around it, rather than hanging and looking like a stall.
 *
 * USAGE
 *   node scripts/judge-calibration-record.mjs [--dry-run] [--only <fixture-id>] [--model <id>]
 *
 *   --dry-run   print what would be recorded; make no API calls and write nothing
 *   --only      re-record a single fixture (by id, e.g. fx-03-strong-slugify)
 *   --model     override the judge model (default: the sonnet-tier alias, matching the blind reviewer)
 *
 * AFTER RECORDING
 *   1. Inspect the diff in judge-outputs/ — a large swing is a finding, not a rubber stamp.
 *   2. node scripts/judge-calibration.mjs --check      # metrics still within threshold?
 *   3. node scripts/judge-calibration.mjs --write-baseline   # store new metrics + prompt hash
 */

import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { execFileSync } from 'child_process';
import { JUDGE_PROMPT_REL, readPromptHash } from './judge-calibration.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const CAL_DIR = join(ROOT, 'framework', 'quality', 'calibration');
const FIXTURES_DIR = join(CAL_DIR, 'fixtures');
const OUTPUTS_DIR = join(CAL_DIR, 'judge-outputs');

/**
 * Pure: is this process running inside a Claude Code session?
 * `claude -p` hangs when nested, so we refuse rather than appear to stall.
 * Exported for the self-test.
 */
export function detectNestedSession(env = process.env) {
  const markers = [
    'CLAUDE_PROJECT_DIR',
    'CLAUDE_AGENT_TEAMS_MEMBER',
    'CLAUDECODE',
    'CLAUDE_CODE_SESSION_ID',
  ];
  const hit = markers.find((m) => env[m]);
  return hit ? { nested: true, marker: hit } : { nested: false, marker: null };
}

/** Pure: build the judge prompt for one fixture. Exported for the self-test. */
export function buildJudgePrompt(promptText, fixture) {
  return [
    promptText,
    '',
    '---',
    '',
    '# Card under review',
    '',
    JSON.stringify(fixture, null, 2),
    '',
    'Respond with ONLY the JSON verdict object described above. No prose, no code fence.',
  ].join('\n');
}

/** Pure: strip a ```json fence if the model wrapped its answer. Exported for the self-test. */
export function extractJson(raw) {
  if (typeof raw !== 'string') return null;
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
  const candidate = (fenced ? fenced[1] : raw).trim();
  try { return JSON.parse(candidate); } catch { return null; }
}

function main() {
  const argv = process.argv.slice(2);
  const dryRun = argv.includes('--dry-run');
  const onlyIdx = argv.indexOf('--only');
  const only = onlyIdx >= 0 ? argv[onlyIdx + 1] : null;
  const modelIdx = argv.indexOf('--model');
  const model = modelIdx >= 0 ? argv[modelIdx + 1] : 'sonnet';

  const nested = detectNestedSession();
  if (nested.nested && !dryRun) {
    process.stderr.write(
      `[record] REFUSING TO RUN: detected a Claude Code session (${nested.marker} is set).\n` +
      '[record] `claude -p` hangs indefinitely in nested sessions. Run this from a plain shell\n' +
      '[record] (a normal terminal, outside Claude Code), then re-run --check and --write-baseline.\n'
    );
    process.exit(1);
  }

  if (!existsSync(FIXTURES_DIR)) {
    process.stderr.write(`[record] no fixtures dir at ${FIXTURES_DIR}\n`);
    process.exit(1);
  }
  const promptPath = join(ROOT, JUDGE_PROMPT_REL);
  if (!existsSync(promptPath)) {
    process.stderr.write(`[record] judge prompt missing at ${JUDGE_PROMPT_REL}\n`);
    process.exit(1);
  }
  const promptText = readFileSync(promptPath, 'utf8');

  let fixtures = readdirSync(FIXTURES_DIR).filter((f) => f.endsWith('.json')).sort();
  if (only) fixtures = fixtures.filter((f) => f.replace(/\.json$/, '') === only);
  if (fixtures.length === 0) {
    process.stderr.write(`[record] no fixtures matched${only ? ` --only ${only}` : ''}\n`);
    process.exit(1);
  }

  process.stdout.write(`[record] judge prompt : ${JUDGE_PROMPT_REL}\n`);
  process.stdout.write(`[record] prompt sha256: ${readPromptHash(ROOT)}\n`);
  process.stdout.write(`[record] model        : ${model}\n`);
  process.stdout.write(`[record] fixtures     : ${fixtures.length}${dryRun ? '  (DRY RUN — nothing will be written)' : ''}\n\n`);

  if (dryRun) {
    for (const f of fixtures) process.stdout.write(`  would record ${f.replace(/\.json$/, '')}\n`);
    process.stdout.write('\n[record] dry run complete — no API calls made, no files written.\n');
    process.exit(0);
  }

  if (!existsSync(OUTPUTS_DIR)) mkdirSync(OUTPUTS_DIR, { recursive: true });

  let recorded = 0;
  let failed = 0;
  for (const file of fixtures) {
    const id = file.replace(/\.json$/, '');
    const fixture = JSON.parse(readFileSync(join(FIXTURES_DIR, file), 'utf8'));
    process.stdout.write(`  • ${id} ... `);
    try {
      const out = execFileSync('claude', ['-p', buildJudgePrompt(promptText, fixture), '--model', model], {
        encoding: 'utf8',
        maxBuffer: 8 * 1024 * 1024,
      });
      const verdict = extractJson(out);
      if (!verdict) {
        process.stdout.write('FAILED (no parseable JSON verdict)\n');
        failed++;
        continue;
      }
      writeFileSync(join(OUTPUTS_DIR, file), JSON.stringify(verdict, null, 2) + '\n');
      process.stdout.write('recorded\n');
      recorded++;
    } catch (err) {
      process.stdout.write(`FAILED (${err.message.split('\n')[0]})\n`);
      failed++;
    }
  }

  process.stdout.write(`\n[record] ${recorded} recorded, ${failed} failed\n`);
  if (failed > 0) {
    process.stderr.write('[record] some fixtures failed — recordings are INCOMPLETE, do not write a baseline yet.\n');
    process.exit(1);
  }
  process.stdout.write('[record] next: node scripts/judge-calibration.mjs --check\n');
  process.stdout.write('[record] then: node scripts/judge-calibration.mjs --write-baseline\n');
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) main();
